function gen_call(name, fn, nout)
    global TST_PASS TST_FAIL %#ok<GVMIS>
    try
        if nout == 0
            fn();
        else
            out = cell(1, nout);
            [out{1:nout}] = fn(); %#ok<NASGU>
        end
        TST_PASS = TST_PASS + 1;
    catch err
        TST_FAIL = TST_FAIL + 1;
        fprintf(2, '  FAIL  gen %s: %s\n', name, err.message);
    end
end
